'use strict';
const nutritionMacroKeys=['kcal','protein','carbs','fat'];
function nutritionQuantity(value){const text=String(value).trim(),parts=text.replace(',','.').split('/'),n=parts.length===2?Number(parts[0])/Number(parts[1]):Number(parts[0]);if(!/^(\d+([.,]\d+)?|\d+\/\d+)$/.test(text)||!Number.isFinite(n)||n<=0||n>100000)throw Error('Informe uma quantidade válida maior que zero.');return n}
function nutritionFoodRow(food={quantity:'',unit:'',name:''}){return `<div class="nutri-food-row nutri-food-nutrients"><label>Quantidade<input name="foodQuantity" inputmode="decimal" required maxlength="20" placeholder="3" value="${esc(food.quantity)}"></label><label>Unidade<input name="foodUnit" required maxlength="50" list="nutritionunits" placeholder="un" value="${esc(food.unit)}"></label><label class="nutri-food-name">Alimento<input name="foodName" required maxlength="200" placeholder="Ovos" value="${esc(food.name)}"></label><button type="button" class="nutri-food-remove" aria-label="Remover alimento">${icon('trash')}</button><div class="nutri-food-nutrient-fields"><p>Valores por <b class="nutri-nutrient-unit">1 ${esc(food.unit||'unidade da medida escolhida')}</b></p><div class="pair">${nutritionFoodMacro('kcal','Kcal',food.kcal)}${nutritionFoodMacro('carbs','Carboidratos · g',food.carbs)}${nutritionFoodMacro('protein','Proteína · g',food.protein)}${nutritionFoodMacro('fat','Lipídios · g',food.fat)}</div><small>A quantidade multiplica estes valores.</small></div></div>`}
function nutritionFoodMacro(key,label,value){return `<label>${label}<input name="food${key[0].toUpperCase()+key.slice(1)}" inputmode="decimal" maxlength="20" placeholder="0" value="${esc(value??'')}"></label>`}
function nutritionFoodItems(form){return [...form.querySelectorAll('.nutri-food-row')].map(row=>{const item={quantity:row.querySelector('[name="foodQuantity"]').value.trim(),unit:row.querySelector('[name="foodUnit"]').value.trim(),name:row.querySelector('[name="foodName"]').value.trim()};nutritionQuantity(item.quantity);if(!item.unit||!item.name)throw Error('Preencha a unidade e o nome de cada alimento.');for(const key of nutritionMacroKeys){const text=row.querySelector(`[name="food${key[0].toUpperCase()+key.slice(1)}"]`).value.trim();if(!text)throw Error('Preencha os quatro valores nutricionais de cada alimento. Use 0 quando necessário.');item[key]=nutritionDecimal(text)}return item})}
function nutritionFoodTotals(items){const totals={kcal:0,protein:0,carbs:0,fat:0};for(const item of items){const amount=nutritionQuantity(item.quantity);for(const key of nutritionMacroKeys)totals[key]+=amount*item[key]}for(const key of nutritionMacroKeys){totals[key]=Math.round((totals[key]+Number.EPSILON)*100)/100;if(!Number.isFinite(totals[key])||totals[key]>100000)throw Error('O total da refeição excede o limite permitido.')}return totals}
function nutritionReadMealValues(form,previous){const foods=nutritionReadFoods(form),blank=[...form.querySelectorAll('.nutri-food-nutrient-fields input')].every(input=>!input.value.trim());if(previous&&!previous.foodItems&&blank&&JSON.stringify(foods)===JSON.stringify(previous.foods))return {foods,...Object.fromEntries(nutritionMacroKeys.map(key=>[key,previous[key]]))};const foodItems=nutritionFoodItems(form);return {foods,foodItems,...nutritionFoodTotals(foodItems)}}
function nutritionTotalsPreview(previous){return `<section class="nutri-calculated"><h3>Total da refeição</h3><p>Calculado pela quantidade × valores de cada alimento.</p><div class="nutri-macros">${nutritionMacroKeys.map(key=>`<span><b data-nutritotal="${key}">${previous?nutritionNumber(previous[key]):'—'}</b> ${key==='kcal'?'kcal':key==='protein'?'g proteína':key==='carbs'?'g carboidratos':'g lipídios'}</span>`).join('')}</div><small id="nutritioncalcstatus" role="status">${previous&&!previous.foodItems?'Valores anteriores preservados. Preencha os nutrientes de todos os alimentos para recalcular.':'Preencha os alimentos para calcular.'}</small></section>`}
function nutritionBindFoodCalculation(previous){const form=$('#nutritionmealform');const update=()=>{form.querySelectorAll('.nutri-food-row').forEach(row=>{row.querySelector('.nutri-nutrient-unit').textContent='1 '+(row.querySelector('[name="foodUnit"]').value.trim()||'unidade da medida escolhida')});try{const values=nutritionReadMealValues(form,previous);for(const key of nutritionMacroKeys)form.querySelector(`[data-nutritotal="${key}"]`).textContent=nutritionNumber(values[key]);$('#nutritioncalcstatus').textContent=values.foodItems?'Total atualizado automaticamente.':'Valores anteriores preservados. Preencha os nutrientes para recalcular.'}catch(error){for(const output of form.querySelectorAll('[data-nutritotal]'))output.textContent='—';$('#nutritioncalcstatus').textContent=error.message}};form.addEventListener('input',update);form.addEventListener('click',event=>{if(event.target.closest('#nutritionaddfood,.nutri-food-remove'))update()});update()}
